/**
 * Shared-album fixtures (`fixtures/album/<trip>.json`, generated by
 * `fixtures/_gen/album.mjs`). File shape:
 *
 * ```
 * { fixtureVersion, groupId, tripId, photos: Photo[], labels: { [photoId]: {...} },
 *   consentTimeline: [{ at, memberId, photos }] }
 * ```
 *
 * `photos` are exactly the `Photo` interface. `labels` (who is in the shot,
 * place name, highlight ground truth) and `consentTimeline` are eval ground
 * truth; the mock reads only `photos`. Captions are untrusted text.
 */
import { parseIso } from '@trav/core';
import type { Photo } from '../../interfaces/album.js';
import type { GeoPoint } from '../../interfaces/common.js';
import {
  asArr,
  asObj,
  bool,
  deepFreeze,
  fixtureFail,
  listFixtureJson,
  optNum,
  optStr,
  readFixtureJson,
  str,
} from '../transactions/fixtureFiles.js';

export interface AlbumFixture {
  readonly groupId: string;
  readonly tripId: string;
  readonly photos: readonly Photo[];
}

export const QUALITY_TAGS: ReadonlySet<string> = new Set([
  'good',
  'ok',
  'bad',
  'screenshot',
  'receipt',
  'blurry',
]);
const MIME_RE = /^(?:image|video)\/[a-z0-9.+-]+$/;

function iso(
  o: Record<string, unknown>,
  key: string,
  where: string,
  required: boolean,
): string | undefined {
  const v = required ? str(o, key, where) : optStr(o, key, where);
  if (v === undefined) return undefined;
  try {
    parseIso(v);
  } catch {
    fixtureFail(`${where}.${key}`, `expected ISO date-time with offset, got "${v}"`);
  }
  return v;
}

function dimension(o: Record<string, unknown>, key: string, where: string): number {
  const n = optNum(o, key, where);
  if (n === undefined || !Number.isSafeInteger(n) || n < 0)
    fixtureFail(`${where}.${key}`, 'expected a non-negative integer');
  return n;
}

function parseGeo(v: unknown, where: string): GeoPoint | undefined {
  if (v === undefined || v === null) return undefined;
  const o = asObj(v, where);
  const lat = optNum(o, 'lat', where);
  const lon = optNum(o, 'lon', where);
  if (lat === undefined || lon === undefined || Math.abs(lat) > 90 || Math.abs(lon) > 180)
    fixtureFail(where, 'bad lat/lon');
  return { lat, lon };
}

export function parsePhoto(raw: unknown, groupId: string, tripId: string, where: string): Photo {
  const o = asObj(raw, where);
  const photoGroup = str(o, 'groupId', where);
  const photoTrip = str(o, 'tripId', where);
  if (photoGroup !== groupId || photoTrip !== tripId)
    fixtureFail(where, `photo belongs to ${photoGroup}/${photoTrip}, not ${groupId}/${tripId}`);
  const mimeType = str(o, 'mimeType', where);
  if (!MIME_RE.test(mimeType)) fixtureFail(`${where}.mimeType`, `unsupported "${mimeType}"`);
  const qualityTag = optStr(o, 'qualityTag', where);
  if (qualityTag !== undefined && !QUALITY_TAGS.has(qualityTag))
    fixtureFail(`${where}.qualityTag`, `unknown "${qualityTag}"`);
  const takenAt = iso(o, 'takenAt', where, false);
  const caption = optStr(o, 'caption', where);
  const location = parseGeo(o['location'], `${where}.location`);
  return {
    photoId: str(o, 'photoId', where),
    groupId,
    tripId,
    ownerMemberId: str(o, 'ownerMemberId', where),
    mimeType,
    width: dimension(o, 'width', where),
    height: dimension(o, 'height', where),
    url: str(o, 'url', where),
    thumbnailUrl: str(o, 'thumbnailUrl', where),
    ...(takenAt === undefined ? {} : { takenAt }),
    ...(location === undefined ? {} : { location }),
    ...(caption === undefined ? {} : { caption }),
    ...(qualityTag === undefined ? {} : { qualityTag }),
    addedAt: iso(o, 'addedAt', where, true) ?? '',
    hidden: bool(o, 'hidden', where),
  };
}

export function parseAlbumFixture(raw: unknown, where = 'album'): AlbumFixture {
  const o = asObj(raw, where);
  const groupId = str(o, 'groupId', where);
  const tripId = str(o, 'tripId', where);
  const photos = asArr(o['photos'], `${where}.photos`).map((p, i) =>
    parsePhoto(p, groupId, tripId, `${where}.photos[${i}]`),
  );
  const ids = new Set<string>();
  for (const p of photos) {
    if (ids.has(p.photoId)) fixtureFail(where, `duplicate photo id ${p.photoId}`);
    ids.add(p.photoId);
  }
  return deepFreeze({ groupId, tripId, photos });
}

/** Loads every `fixtures/<dir...>/*.json` album fixture, sorted by file name. */
export function loadAlbumFixtures(dir: readonly string[] = ['album']): readonly AlbumFixture[] {
  return listFixtureJson(dir).map((name) =>
    parseAlbumFixture(readFixtureJson(dir, name), `fixtures/${dir.join('/')}/${name}.json`),
  );
}
